contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: try calling play with an arbitrary amount
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: the call reverts iff the sent amount is not equal to C.TICKET_AMOUNT (10).
        // We observe TICKET_AMOUNT indirectly by checking that non-revert implies amount == 10,
        // and amount == 10 implies non-revert. Use the public getter c.pot and address(c).balance
        // only as allowed observables if needed; here we assert the equivalence between revert and amount.
        assert(reverted == (amount != 10));
    }

    receive() external payable {}
}

